    {
      "clause_type": "sub_processors",
      "reason": "The sub-processor list is referenced as published on the Provider's website but is not attached or reproduced; the identities, locations, and transfer mechanisms of sub-processors cannot be reviewed."
    },
    {
      "clause_type": "data_protection",
      "reason": "No Data Processing Addendum, Annex, or standard contractual clauses are attached; Art. 28 detail (processing purposes, categories of data, international transfer safeguards, audit rights, breach notification) cannot be assessed."
    },
    {
      "clause_type": "service_level",
      "reason": "No SLA schedule or service-credit exhibit is included; downtime measurement method, exclusions, and remedies for missing 99.5% are indeterminate."
    },
    {
      "clause_type": "fees",
      "reason": "No pricing schedule or order form is provided, so the baseline fees, payment terms, and the practical magnitude of the increase right cannot be evaluated."
    },
    {
      "clause_type": "security",
      "reason": "No security schedule, control list, or certification evidence is attached, so 'industry standard' cannot be benchmarked."
    },
    {
      "clause_type": "governing_law_and_dispute_resolution",
      "reason": "The document contains no governing law, jurisdiction, or dispute-resolution provision; enforceability of the liability cap, indemnity, and data licence cannot be assessed without it."
    },
    {
      "clause_type": "termination_for_cause",
      "reason": "No termination-for-breach, suspension, or effect-of-termination provision (other than data deletion) appears in the excerpt provided."
    },
    {
      "clause_type": "confidentiality",
      "reason": "No confidentiality clause is present in the document supplied; unable to determine how Customer Data is protected outside the data protection section."
    }
  ],
  "citations": [
    {
      "clause_type": "service_level",
      "quote": "The Provider shall use commercially reasonable efforts to maintain 99.5% monthly\nuptime, measured over each calendar month."
    },
    {
      "clause_type": "data_protection",
      "quote": "The Provider shall process Customer Personal Data only on documented instructions\nfrom the Customer, in accordance with applicable data protection law."
    },
    {
      "clause_type": "limitation_of_liability",
      "quote": "The Provider's total liability under this Agreement shall not exceed the fees paid\nin the twelve (12) months preceding the claim."
    },
    {
      "clause_type": "term",
      "quote": "The initial term of this Agreement is twelve (12) months from the effective date."
    },
    {
      "clause_type": "auto_renewal",
      "quote": "This Agreement renews automatically for successive twelve (12) month terms unless\neither party gives ninety (90) days written notice prior to the end of the\nthen-current term."
    },
    {
      "clause_type": "sub_processors",
      "quote": "The Provider may appoint sub-processors to process Customer Personal Data and\nshall publish an updated list on its website. No notice to the Customer is\nrequired."
    },
    {
      "clause_type": "security",
      "quote": "The Provider shall maintain industry standard security measures appropriate to a\nprovider of its size."
    },
    {
      "clause_type": "intellectual_property_data_license",
      "quote": "The Customer grants the Provider a perpetual, irrevocable, worldwide licence to\nuse Customer Data, including Customer Personal Data, to develop and train the\nProvider's machine learning models and to create derivative products."
    },
    {
      "clause_type": "indemnity",
      "quote": "The Customer shall indemnify and hold harmless the Provider against all claims\narising from the use of the service, including claims that the service infringes\nthe intellectual property rights of a third party."
    },
    {
      "clause_type": "fees",
      "quote": "The Provider may increase the fees at any time on thirty (30) days written notice.\nThe Customer has no right to terminate on account of a fee increase."
    },
    {
      "clause_type": "data_export_and_deletion",
      "quote": "The Provider shall delete all Customer Data seven (7) days after termination. The\nCustomer may request an export within that period."
    }
  ],
  "clauses": [
    {
      "clause_type": "service_level",
      "text": "Commercially reasonable efforts to maintain 99.5% monthly uptime, measured per calendar month."
    },
    {
      "clause_type": "data_protection",
      "text": "Provider processes Customer Personal Data only on documented Customer instructions, per applicable data protection law."
    },
    {
      "clause_type": "limitation_of_liability",
      "text": "Provider's aggregate liability capped at fees paid in the 12 months preceding the claim."
    },
    {
      "clause_type": "term",
      "text": "Initial term of twelve (12) months from the effective date."
    },
    {
      "clause_type": "auto_renewal",
      "text": "Automatic renewal for successive 12-month terms unless 90 days' prior written notice is given."
    },
    {
      "clause_type": "sub_processors",
      "text": "Provider may appoint sub-processors and publish an updated list online; no notice to Customer required."
