      "clause_type": "intellectual_property_data_license",
      "text": "Customer grants Provider a perpetual, irrevocable, worldwide licence to use Customer Data, including Personal Data, for ML model training and derivative products."
    },
    {
      "clause_type": "indemnity",
      "text": "Customer indemnifies Provider for all claims arising from use of the service, including third-party IP infringement claims."
    },
    {
      "clause_type": "fees",
      "text": "Provider may raise fees at any time on 30 days' notice; Customer has no termination right for price increases."
