  "risk_flags": [
    {
      "clause_type": "intellectual_property_data_license",
      "rationale": "Perpetual, irrevocable licence to use Customer Personal Data for ML training conflicts with the Section 2 'documented instructions' processor role and is very difficult to reconcile with GDPR lawful-basis, purpose-limitation and erasure obligations for a German customer.",
      "severity": "high"
    },
    {
      "clause_type": "indemnity",
      "rationale": "One-way indemnity requiring the Customer to cover third-party IP infringement claims about the Provider's own service is a reverse allocation of risk; normally the Provider indemnifies for IP infringement.",
      "severity": "high"
    },
    {
      "clause_type": "sub_processors",
      "rationale": "No notice and no objection right for new sub-processors falls short of the customary GDPR Art. 28(2)/(4) requirement for prior information and an opportunity to object.",
      "severity": "high"
    },
    {
      "clause_type": "data_export_and_deletion",
      "rationale": "A 7-day post-termination deletion window with export only on request risks irrecoverable data loss; no defined export format, SLA, or assistance obligation.",
      "severity": "high"
    },
    {
      "clause_type": "fees",
      "rationale": "Unlimited fee increases on 30 days' notice with no cap and no corresponding termination right leaves the Customer economically exposed during the term.",
      "severity": "medium"
    },
    {
      "clause_type": "auto_renewal",
      "rationale": "90-day notice window before a 12-month auto-renewal is long; missing the window locks in another full year, compounded by the uncapped fee-increase right.",
      "severity": "medium"
    },
    {
      "clause_type": "limitation_of_liability",
      "rationale": "12-month fee cap appears to apply to all liability with no stated carve-outs for data breach, confidentiality, IP indemnity, or wilful misconduct; also appears one-sided in the Provider's favour.",
      "severity": "medium"
    },
    {
      "clause_type": "service_level",
      "rationale": "'Commercially reasonable efforts' toward 99.5% uptime creates no firm commitment, and no service credits, measurement methodology, or exclusions are stated in the document.",
      "severity": "medium"
    },
    {
      "clause_type": "security",
      "rationale": "'Industry standard ... appropriate to a provider of its size' is subjective and unmeasurable; no specific controls, certifications (e.g. ISO 27001, SOC 2), audit rights, or breach-notification timeline are set out.",
      "severity": "medium"
    }
  ]
}
